  9258  static bool
  9259  add_label_patch_to_list(BranchBlock *frame_csp, uint8 patch_type,
  9260                          uint8 *p_code_compiled, char *error_buf,
  9261                          uint32 error_buf_size)
  9262  {
  9263      BranchBlockPatch *patch =
  9264          loader_malloc(sizeof(BranchBlockPatch), error_buf, error_buf_size);
  9265      if (!patch) {
  9266          return false;
  9267      }
  9268      patch->patch_type = patch_type;
  9269      patch->code_compiled = p_code_compiled;
  9270      if (!frame_csp->patch_list) {
  9271          frame_csp->patch_list = patch;
  9272          patch->next = NULL;
  9273      }
  9274      else {
  9275          patch->next = frame_csp->patch_list;
  9276          frame_csp->patch_list = patch;
  9277      }
  9278      return true;
  9279  }
