  9281  static void
  9282  apply_label_patch(WASMLoaderContext *ctx, uint8 depth, uint8 patch_type)
  9283  {
  9284      BranchBlock *frame_csp = ctx->frame_csp - depth;
  9285      BranchBlockPatch *node = frame_csp->patch_list;
  9286      BranchBlockPatch *node_prev = NULL, *node_next;
  9287
  9288      if (!ctx->p_code_compiled)
  9289          return;
  9290
  9291      while (node) {
  9292          node_next = node->next;
  9293          if (node->patch_type == patch_type) {
  9294              STORE_PTR(node->code_compiled, ctx->p_code_compiled);
  9295              if (node_prev == NULL) {
  9296                  frame_csp->patch_list = node_next;
  9297              }
  9298              else {
  9299                  node_prev->next = node_next;
  9300              }
  9301              wasm_runtime_free(node);
  9302          }
  9303          else {
  9304              node_prev = node;
  9305          }
  9306          node = node_next;
  9307      }
  9308  }
