 10345  static bool
 10346  check_memory_align_equal(uint8 opcode, uint32 align, char *error_buf,
 10347                           uint32 error_buf_size)
 10348  {
 10349      uint8 wait_notify_aligns[] = { 2, 2, 3 };
 10350      uint8 mem_access_aligns[] = {
 10351          2, 3, 0, 1, 0, 1, 2,
 10352      };
 10353      uint8 expect;
 10354
 10355      bh_assert((opcode <= WASM_OP_ATOMIC_WAIT64)
 10356                || (opcode >= WASM_OP_ATOMIC_I32_LOAD
 10357                    && opcode <= WASM_OP_ATOMIC_RMW_I64_CMPXCHG32_U));
 10358      if (opcode <= WASM_OP_ATOMIC_WAIT64) {
 10359          expect = wait_notify_aligns[opcode - WASM_OP_ATOMIC_NOTIFY];
 10360      }
 10361      else {
 10362          /* 7 opcodes in every group */
 10363          expect = mem_access_aligns[(opcode - WASM_OP_ATOMIC_I32_LOAD) % 7];
 10364      }
 10365      if (align != expect) {
 10366          set_error_buf(error_buf, error_buf_size,
 10367                        "alignment isn't equal to natural");
 10368          return false;
 10369      }
 10370      return true;
 10371  }
