  8112  static bool
  8113  wasm_loader_init_local_use_masks(WASMLoaderContext *ctx, uint32 local_count,
  8114                                   char *error_buf, uint32 error_buf_size)
  8115  {
  8116      BranchBlock *current_csp = ctx->frame_csp - 1;
  8117      uint32 local_mask_size;
  8118
  8119      if (local_count == 0) {
  8120          current_csp->local_use_mask_size = 0;
  8121          return true;
  8122      }
  8123
  8124      /* if current_csp->local_use_mask is not NULL, then it is re-init masks for
  8125       * else branch, we don't need to allocate memory again */
  8126      if (!current_csp->local_use_mask) {
  8127          local_mask_size = (local_count + 7) / sizeof(uint8);
  8128          if (!(current_csp->local_use_mask =
  8129                    loader_malloc(local_mask_size, error_buf, error_buf_size))) {
  8130              return false;
  8131          }
  8132          current_csp->local_use_mask_size = local_mask_size;
  8133      }
  8134      else {
  8135          local_mask_size = current_csp->local_use_mask_size;
  8136          bh_assert(current_csp->label_type == LABEL_TYPE_IF);
  8137      }
  8138
  8139      if (current_csp->label_type != LABEL_TYPE_FUNCTION) {
  8140          /* For non-function blocks, inherit the use status from parent block */
  8141          BranchBlock *parent_csp = current_csp - 1;
  8142
  8143          bh_assert(parent_csp >= ctx->frame_csp_bottom);
  8144          bh_assert(parent_csp->local_use_mask);
  8145
  8146          bh_memcpy_s(current_csp->local_use_mask, local_mask_size,
  8147                      parent_csp->local_use_mask, local_mask_size);
  8148      }
  8149
  8150      return true;
  8151  }
