  9371          if (frame_csp->label_type == LABEL_TYPE_LOOP)
  9372              /* Use start_dynamic_offset which was set in
  9373                 copy_params_to_dynamic_space */
  9374              dynamic_offset = frame_csp->start_dynamic_offset
  9375                               + wasm_get_cell_num(types, arity);
  9376          else
  9377              dynamic_offset =
  9378                  frame_csp->dynamic_offset + wasm_get_cell_num(types, arity);
  9379          if (is_br)
  9380              ctx->dynamic_offset = dynamic_offset;
  9381          for (i = (int32)arity - 1; i >= 0; i--) {
  9382              cell = (uint8)wasm_value_type_cell_num(types[i]);
  9383              dynamic_offset -= cell;
  9384              emit_operand(ctx, dynamic_offset);
  9385          }
  9386      }
  9387
  9388      /* Part f */
  9389      if (frame_csp->label_type == LABEL_TYPE_LOOP) {
  9390          wasm_loader_emit_ptr(ctx, frame_csp->code_compiled);
  9391      }
